questions.correct_answer:
function debounceUtility_1(fn, delay) {
    let timerId = null;
    const debounced = function(...args) {
        if (timerId) clearTimeout(timerId);
        timerId = setTimeout(() => {
            fn.apply(this, args);
        }, delay);
    };
    debounced.cancel = () => { if (timerId) clearTimeout(timerId); };
    return debounced;
}

